import semver
import sys

# Test R1: no arguments
print('Test 1: main(cliargs=[]) ...')
try:
    semver.main(cliargs=[])
except SystemExit as e:
    print(f'  SystemExit({e.code}) raised')
except AttributeError as e:
    print(f'  AttributeError raised: {e}')
except Exception as e:
    print(f'  Other error: {type(e).__name__}: {e}')

# Test R1: bump without subcommand
print('Test 2: main(cliargs=[\"bump\"]) ...')
try:
    semver.main(cliargs=['bump'])
except SystemExit as e:
    print(f'  SystemExit({e.code}) raised')
except AttributeError as e:
    print(f'  AttributeError raised: {e}')
except Exception as e:
    print(f'  Other error: {type(e).__name__}: {e}')

# Test: check subcommand
print('Test 3: main(cliargs=[\"check\", \"1.2.3\"]) ...')
try:
    rc = semver.main(cliargs=['check', '1.2.3'])
    print(f'  return code: {rc}')
except Exception as e:
    print(f'  Error: {type(e).__name__}: {e}')
